/**
 * Dev - Projects
 *
 * @module server/handlers/dev/projects
 */
import { BaseHandler } from "../../response/base.js";
import { HTTP_OK, PRIORITY_HIGH } from "../../../../utils/constants/index.js";
import { PROJECTS_SHELL_HTML } from "./html-shell.js";
import { handleProjectsAPI } from "./api.js";
import { handleProjectsUI } from "./ui-handler.js";
import { createDevNotFoundResponse } from "../shared/not-found-response.js";
import { createDevUiAssetsUnavailableResponse, omitHeadResponseBody, } from "../shared/dev-ui-bundle-response.js";
import { isTrustedLocalControlRequest } from "../../../../security/http/local-control-request.js";
const PROJECTS_ALLOWED_METHODS = "GET, HEAD";
function cancelRejectedRequestBody(req) {
    try {
        void req.body?.cancel().catch(() => { });
    }
    catch {
        // Preserve the deterministic method response if a hostile stream is
        // already locked or fails while cancellation is attempted.
    }
}
export class ProjectsHandler extends BaseHandler {
    browserBundle;
    constructor(provider) {
        super();
        this.browserBundle = provider?.browserBundle;
    }
    metadata = {
        name: "ProjectsHandler",
        priority: PRIORITY_HIGH,
        patterns: [
            { pattern: "/", exact: true },
            { pattern: "/_projects", exact: false },
        ],
        enabled: (ctx) => {
            const isVeryfrontDomain = ctx.parsedDomain?.isVeryfrontDomain === true;
            const hasNoSlug = !ctx.projectSlug;
            // Enable for veryfront domains without a project slug
            // Works in both proxy mode and local multi-project mode
            return isVeryfrontDomain && hasNoSlug;
        },
    };
    shouldHandle(req, ctx) {
        if (!this.metadata.enabled?.(ctx))
            return false;
        if (!isTrustedLocalControlRequest(req))
            return false;
        const { pathname } = new URL(req.url);
        return pathname === "/" || pathname.startsWith("/_projects");
    }
    async handle(req, ctx) {
        if (!this.shouldHandle(req, ctx))
            return this.continue();
        if (req.method !== "GET" && req.method !== "HEAD") {
            cancelRejectedRequestBody(req);
            return this.respond(new Response("Method Not Allowed", {
                status: 405,
                headers: {
                    Allow: PROJECTS_ALLOWED_METHODS,
                    "Cache-Control": "no-store",
                    "Content-Type": "text/plain; charset=utf-8",
                },
            }));
        }
        const { pathname } = new URL(req.url);
        if (pathname === "/" || pathname === "/_projects" || pathname === "/_projects/") {
            if (this.browserBundle === undefined) {
                return this.respond(omitHeadResponseBody(req, createDevUiAssetsUnavailableResponse()));
            }
            return this.respond(omitHeadResponseBody(req, this.createResponseBuilder(ctx).withCache("no-store").withContentType("text/html; charset=utf-8", PROJECTS_SHELL_HTML, HTTP_OK)));
        }
        if (pathname.startsWith("/_projects/ui/")) {
            const response = handleProjectsUI(req, this.browserBundle);
            if (response)
                return this.respond(omitHeadResponseBody(req, response));
            return this.respond(omitHeadResponseBody(req, createDevNotFoundResponse()));
        }
        if (pathname.startsWith("/_projects/api/")) {
            const response = await handleProjectsAPI(req, ctx);
            if (response)
                return this.respond(omitHeadResponseBody(req, response));
            return this.respond(omitHeadResponseBody(req, createDevNotFoundResponse()));
        }
        return this.respond(omitHeadResponseBody(req, createDevNotFoundResponse()));
    }
}
